using System.Net;
using System.Text.Json;
using SeatLayer;
using Xunit;

namespace SeatLayer.Tests;

/// <summary>
/// Holders, Orders, EventSeries and the event sales methods on Events: verb, escaped path,
/// query, JSON body, and which calls carry an Idempotency-Key.
/// </summary>
public class SalesOperationTests
{
    /// <summary>Expected key value meaning "present, generated by the SDK".</summary>
    private const string Generated = "*";

    private static (SeatLayerClient Client, StubHandler Handler) Build(
        IEnumerable<(HttpStatusCode, string, IDictionary<string, string>)> responses,
        int maxRetries = 1)
    {
        var handler = new StubHandler(responses);
        var client = new SeatLayerClient("sk_test_abc", new SeatLayerClientOptions
        {
            HttpClient = new HttpClient(handler),
            MaxRetries = maxRetries,
        });
        return (client, handler);
    }

    private static (HttpStatusCode, string, IDictionary<string, string>) Ok(string body = "{}")
        => (HttpStatusCode.OK, body, new Dictionary<string, string>());

    private static (HttpStatusCode, string, IDictionary<string, string>) Created(string body)
        => (HttpStatusCode.Created, body, new Dictionary<string, string>());

    private static (HttpStatusCode, string, IDictionary<string, string>) RateLimited()
        => ((HttpStatusCode)429, "{\"error\":\"rate_limited\"}",
            new Dictionary<string, string> { ["Retry-After"] = "0" });

    private static string Canonical(string json)
    {
        using var document = JsonDocument.Parse(json);
        return JsonSerializer.Serialize(document.RootElement);
    }

    /// <summary>
    /// <paramref name="body"/> null means no request body. <paramref name="key"/> null means no
    /// Idempotency-Key header; <see cref="Generated"/> means one the SDK made up.
    /// </summary>
    private static void AssertCall(
        StubHandler handler, int index, HttpMethod method, string url, string? body, string? key)
    {
        var call = handler.Calls[index];
        Assert.Equal(method, call.Method);
        Assert.Equal(url, call.Url.AbsoluteUri);

        if (body is null)
        {
            Assert.Null(call.Body);
        }
        else
        {
            Assert.NotNull(call.Body);
            Assert.Equal(Canonical(body), Canonical(call.Body!));
        }

        if (key is null)
        {
            Assert.False(call.Headers.Contains("Idempotency-Key"));
        }
        else
        {
            var sent = call.Headers.GetValues("Idempotency-Key").Single();
            if (key == Generated)
            {
                Assert.False(string.IsNullOrEmpty(sent));
            }
            else
            {
                Assert.Equal(key, sent);
            }
        }
    }

    [Fact]
    public async Task HoldersMapAll14Operations()
    {
        var (client, handler) = Build(Enumerable.Range(0, 15).Select(_ => Ok()));
        var holders = client.Holders;

        await holders.ListCustomersAsync(new CustomerListRequest
        {
            Email = "fan@example.com", HolderRef = "h/1", Cursor = "c/1", Limit = 10,
        });
        await holders.RetrieveHolderAsync("h/1");
        await holders.UpdateHolderAsync("h/1", new HolderUpdateRequest
        {
            Email = "new@example.com", Phone = null, IdempotencyKey = "holder-1",
        });
        await holders.RevokeHolderSessionsAsync("h/1");
        await holders.ListHolderSeasonsAsync("h/1");
        await holders.ListHolderTicketsAsync("h/1", new HolderTicketListRequest
        {
            SeasonKey = "sea/a", From = 1_800_000_000_000, To = 1_800_100_000_000, Limit = 5,
        });
        await holders.RetrieveHolderTicketAsync("h/1", "tkt/1");
        await holders.CreateHolderTransferAsync("h/1", new HolderTransferCreateRequest
        {
            TicketIds = new[] { "tkt_1", "tkt_2" }, ToEmail = "friend@example.com",
        });
        await holders.ListHolderTransfersAsync("h/1");
        await holders.CancelHolderTransferAsync("h/1", "tr/1");
        await holders.AcceptHolderTransferAsync("h/1", "tr/1");
        await holders.CreateHolderReturnAsync("h/1", new HolderReturnCreateRequest
        {
            TicketIds = new[] { "tkt_0123456789abcdef01234567" }, IdempotencyKey = "return-1",
        });
        await holders.CreateHolderRenewalCheckoutAsync("h/1", "offer/1", new SeasonRenewalCheckoutRequest
        {
            ReturnUrl = "https://tickets.example/renewed", BuyerEmail = "cara@example.com",
            BuyerName = "Cara", Provider = "stripe", IdempotencyKey = "renew-1",
        });
        await holders.DeclineHolderRenewalOfferAsync("h/1", "offer/1", "Moving away");
        await holders.DeclineHolderRenewalOfferAsync("h/1", "offer/1");

        Assert.Equal(15, handler.Calls.Count);
        const string holder = "https://api.seatlayer.io/v1/holders/h%2F1";
        AssertCall(handler, 0, HttpMethod.Get,
            "https://api.seatlayer.io/v1/customers?email=fan%40example.com&holderRef=h%2f1&cursor=c%2f1&limit=10",
            null, null);
        AssertCall(handler, 1, HttpMethod.Get, holder, null, null);
        // Name was never assigned, so it stays out; Phone was assigned null, so it is cleared.
        AssertCall(handler, 2, HttpMethod.Patch, holder,
            "{\"email\":\"new@example.com\",\"phone\":null}", "holder-1");
        AssertCall(handler, 3, HttpMethod.Post, holder + "/sessions/revoke", "{}", null);
        AssertCall(handler, 4, HttpMethod.Get, holder + "/seasons", null, null);
        AssertCall(handler, 5, HttpMethod.Get,
            holder + "/tickets?seasonKey=sea%2fa&from=1800000000000&to=1800100000000&limit=5", null, null);
        AssertCall(handler, 6, HttpMethod.Get, holder + "/tickets/tkt%2F1", null, null);
        AssertCall(handler, 7, HttpMethod.Post, holder + "/transfers",
            "{\"ticketIds\":[\"tkt_1\",\"tkt_2\"],\"toEmail\":\"friend@example.com\"}", Generated);
        AssertCall(handler, 8, HttpMethod.Get, holder + "/transfers", null, null);
        AssertCall(handler, 9, HttpMethod.Post, holder + "/transfers/tr%2F1/cancel", null, null);
        AssertCall(handler, 10, HttpMethod.Post, holder + "/transfers/tr%2F1/accept", null, null);
        AssertCall(handler, 11, HttpMethod.Post, holder + "/returns",
            "{\"ticketIds\":[\"tkt_0123456789abcdef01234567\"]}", "return-1");
        AssertCall(handler, 12, HttpMethod.Post, holder + "/renewal-offers/offer%2F1/checkout",
            "{\"returnUrl\":\"https://tickets.example/renewed\",\"buyerEmail\":\"cara@example.com\","
            + "\"buyerName\":\"Cara\",\"provider\":\"stripe\"}", "renew-1");
        AssertCall(handler, 13, HttpMethod.Post, holder + "/renewal-offers/offer%2F1/decline",
            "{\"reason\":\"Moving away\"}", null);
        AssertCall(handler, 14, HttpMethod.Post, holder + "/renewal-offers/offer%2F1/decline", "{}", null);
    }

    [Fact]
    public async Task OrdersMapAll9OperationsAndCsvComesBackAsText()
    {
        const string csv = "order,status,total\nA-100,refunded,4500\n";
        var responses = Enumerable.Range(0, 9).Select(_ => Ok()).ToList();
        responses[5] = Ok(csv);
        var (client, handler) = Build(responses);
        var orders = client.Orders;

        await orders.ListOrdersAsync(new OrderListRequest
        {
            EventKey = "ev/1", SeasonKey = "sea/a", Status = "paid", From = 1, To = 2,
            Cursor = "c/1", Limit = 20,
        });
        await orders.RetrieveOrderAsync("ord/1");
        await orders.ListOrderTicketsAsync("ord/1");
        await orders.ListEventOrdersAsync("ev/1", new EventOrderListRequest
        {
            Query = "smith", Status = "paid", PaidBy = "card", From = 1, To = 2,
            Cursor = "c/1", Limit = 20,
        });
        await orders.RetrieveEventOrderAsync("ev/1", "ord/1");
        var exported = await orders.ExportEventOrdersCsvAsync(
            "ev/1", new EventOrderFilterRequest { Status = "refunded" });
        await orders.RefundEventOrderAsync("ev/1", "ord/1");
        await orders.CancelEventOrderAsync("ev/1", "ord/1", new OrderCancelRequest
        {
            Reason = "lost_dispute", NotifyBuyer = false, IdempotencyKey = "cancel-1",
        });
        await orders.ResendEventOrderTicketsAsync("ev/1", "ord/1");

        Assert.Equal(csv, exported);
        Assert.Equal("text/csv", handler.Calls[5].Headers.Accept.Single().MediaType);
        Assert.Equal(9, handler.Calls.Count);
        const string order = "https://api.seatlayer.io/v1/orders/ord%2F1";
        const string eventOrder = "https://api.seatlayer.io/v1/events/ev%2F1/orders/ord%2F1";
        AssertCall(handler, 0, HttpMethod.Get,
            "https://api.seatlayer.io/v1/orders?eventKey=ev%2f1&seasonKey=sea%2fa&status=paid&from=1&to=2&cursor=c%2f1&limit=20",
            null, null);
        AssertCall(handler, 1, HttpMethod.Get, order, null, null);
        AssertCall(handler, 2, HttpMethod.Get, order + "/tickets", null, null);
        AssertCall(handler, 3, HttpMethod.Get,
            "https://api.seatlayer.io/v1/events/ev%2F1/orders?q=smith&status=paid&paidBy=card&from=1&to=2&cursor=c%2f1&limit=20",
            null, null);
        AssertCall(handler, 4, HttpMethod.Get, eventOrder, null, null);
        AssertCall(handler, 5, HttpMethod.Get,
            "https://api.seatlayer.io/v1/events/ev%2F1/orders.csv?status=refunded", null, null);
        AssertCall(handler, 6, HttpMethod.Post, eventOrder + "/refund", "{}", Generated);
        AssertCall(handler, 7, HttpMethod.Post, eventOrder + "/cancel",
            "{\"reason\":\"lost_dispute\",\"notifyBuyer\":false}", "cancel-1");
        AssertCall(handler, 8, HttpMethod.Post, eventOrder + "/resend", "{}", null);
    }

    [Fact]
    public async Task EventSalesMapAll14OperationsWithoutIdempotencyKeys()
    {
        var responses = Enumerable.Range(0, 14).Select(_ => Ok()).ToList();
        responses[13] = (HttpStatusCode.NoContent, "", new Dictionary<string, string>());
        var (client, handler) = Build(responses);
        var events = client.Events;

        await events.RetrieveEventBuyerCheckoutAsync("ev/1");
        await events.ReplaceEventBuyerCheckoutAsync("ev/1", new EventBuyerCheckoutReplaceRequest
        {
            BuyerCheckout = "seatlayer", ExpectedRevision = 3,
        });
        await events.RetrieveEventPaymentGatewayAsync("ev/1", "EUR");
        await events.ReplaceEventPaymentGatewayAsync("ev/1", new EventPaymentGatewayReplaceRequest
        {
            ConnectionId = "conn_1", Provider = null,
        });
        await events.RetrieveEventSalesReadinessAsync("ev/1");
        await events.PreflightEventSalesAsync("ev/1", "ord_1");
        await events.TransitionEventSalesAsync("ev/1", new EventSalesTransitionRequest
        {
            To = "live", ExpectedRevision = 4, Reason = "Launch",
        });
        await events.RetrieveEventBookingFeeAsync("ev/1");
        await events.ReplaceEventBookingFeeAsync("ev/1", null);
        await events.ListEventDiscountCodesAsync("ev/1");
        await events.CreateEventDiscountCodeAsync("ev/1", new EventDiscountCodeCreateRequest
        {
            Code = "EARLY10", Kind = "percent", Percent = 10, MaxUses = 100,
        });
        await events.UpdateEventDiscountCodeAsync("ev/1", "dc/1", new EventDiscountCodeUpdateRequest
        {
            State = "paused", EndsAt = null,
        });
        await events.EndEventDiscountCodeAsync("ev/1", "dc/1");
        var deletion = events.DeleteEventDiscountCodeAsync("ev/1", "dc/1");
        await deletion;

        Assert.True(deletion.IsCompletedSuccessfully);
        Assert.Equal(14, handler.Calls.Count);
        const string seatEvent = "https://api.seatlayer.io/v1/events/ev%2F1";
        AssertCall(handler, 0, HttpMethod.Get, seatEvent + "/buyer-checkout", null, null);
        AssertCall(handler, 1, HttpMethod.Put, seatEvent + "/buyer-checkout",
            "{\"buyerCheckout\":\"seatlayer\",\"expectedRevision\":3}", null);
        AssertCall(handler, 2, HttpMethod.Get, seatEvent + "/payment-gateway?currency=EUR", null, null);
        AssertCall(handler, 3, HttpMethod.Put, seatEvent + "/payment-gateway",
            "{\"connectionId\":\"conn_1\",\"provider\":null}", null);
        AssertCall(handler, 4, HttpMethod.Get, seatEvent + "/sales/readiness", null, null);
        AssertCall(handler, 5, HttpMethod.Post, seatEvent + "/sales/preflight",
            "{\"orderId\":\"ord_1\"}", null);
        AssertCall(handler, 6, HttpMethod.Post, seatEvent + "/sales/transition",
            "{\"to\":\"live\",\"expectedRevision\":4,\"reason\":\"Launch\"}", null);
        AssertCall(handler, 7, HttpMethod.Get, seatEvent + "/booking-fee", null, null);
        AssertCall(handler, 8, HttpMethod.Put, seatEvent + "/booking-fee",
            "{\"bookingFeeMinor\":null}", null);
        AssertCall(handler, 9, HttpMethod.Get, seatEvent + "/discount-codes", null, null);
        AssertCall(handler, 10, HttpMethod.Post, seatEvent + "/discount-codes",
            "{\"code\":\"EARLY10\",\"kind\":\"percent\",\"percent\":10,\"maxUses\":100}", null);
        // EndsAt was assigned null, so the end limit is removed; StartsAt stays out.
        AssertCall(handler, 11, HttpMethod.Patch, seatEvent + "/discount-codes/dc%2F1",
            "{\"state\":\"paused\",\"endsAt\":null}", null);
        AssertCall(handler, 12, HttpMethod.Post, seatEvent + "/discount-codes/dc%2F1/end", null, null);
        AssertCall(handler, 13, HttpMethod.Delete, seatEvent + "/discount-codes/dc%2F1", null, null);
    }

    [Fact]
    public async Task EventSeriesMapAll5OperationsWithHeaderReplay()
    {
        var (client, handler) = Build(Enumerable.Range(0, 5).Select(_ => Ok()));
        var series = client.EventSeries;

        await series.CreateEventSeriesAsync(new EventSeriesCreateRequest
        {
            Name = "Hamlet",
            ChartKey = "chart_1",
            Schedule = new EventSeriesSchedule
            {
                Rule = "weekly", From = "2027-01-04", Count = 3, Times = new[] { "19:30" },
            },
            Timezone = "UTC",
            DurationMinutes = 150,
            DryRun = true,
            IdempotencyKey = "series-1",
        });
        await series.ListEventSeriesAsync(new EventSeriesListRequest { Limit = 10, Cursor = "c/1" });
        await series.RetrieveEventSeriesAsync("ser/1");
        await series.AddEventSeriesDatesAsync("ser/1", new EventSeriesDatesRequest
        {
            Dates = new[] { "2027-02-01T19:30" },
        });
        await series.UpdateEventSeriesAsync("ser/1", new EventSeriesUpdateRequest
        {
            Name = "Hamlet II",
            Prices = new Dictionary<string, object?>
            {
                ["categories"] = new List<object?>
                {
                    new Dictionary<string, object?> { ["key"] = "A", ["price"] = 45 },
                },
            },
            Sales = "on",
            IdempotencyKey = "series-update-1",
        });

        Assert.Equal(5, handler.Calls.Count);
        const string one = "https://api.seatlayer.io/v1/event-series/ser%2F1";
        AssertCall(handler, 0, HttpMethod.Post, "https://api.seatlayer.io/v1/event-series",
            "{\"name\":\"Hamlet\",\"chartKey\":\"chart_1\",\"schedule\":{\"rule\":\"weekly\","
            + "\"from\":\"2027-01-04\",\"count\":3,\"times\":[\"19:30\"]},\"timezone\":\"UTC\","
            + "\"durationMinutes\":150,\"dryRun\":true}",
            "series-1");
        AssertCall(handler, 1, HttpMethod.Get,
            "https://api.seatlayer.io/v1/event-series?limit=10&cursor=c%2f1", null, null);
        AssertCall(handler, 2, HttpMethod.Get, one, null, null);
        AssertCall(handler, 3, HttpMethod.Post, one + "/dates",
            "{\"dates\":[\"2027-02-01T19:30\"]}", Generated);
        AssertCall(handler, 4, HttpMethod.Patch, one,
            "{\"name\":\"Hamlet II\",\"prices\":{\"categories\":[{\"key\":\"A\",\"price\":45}]},\"sales\":\"on\"}",
            "series-update-1");
    }

    [Fact]
    public async Task RequestsWithOptionalBodiesSendEmptyObjects()
    {
        var (client, handler) = Build(Enumerable.Range(0, 3).Select(_ => Ok()));

        await client.Events.ReplaceEventPaymentGatewayAsync("ev_1");
        await client.Seasons.UpdateSeasonRenewalOfferContactAsync(
            "sea_1", "offer_1", new SeasonRenewalContactRequest());
        await client.Holders.UpdateHolderAsync("h_1", new HolderUpdateRequest { Name = "Ana" });

        Assert.Equal("{}", handler.Calls[0].Body);
        Assert.Equal("{}", handler.Calls[1].Body);
        Assert.Equal("{\"name\":\"Ana\"}", handler.Calls[2].Body);
    }

    [Fact]
    public async Task UnsupportedEventMutationsAreNeverRetried()
    {
        var (client, handler) = Build(
            new[] { RateLimited(), RateLimited(), RateLimited() }, maxRetries: 3);

        await Assert.ThrowsAsync<SeatLayerRateLimitException>(
            () => client.Events.CreateEventDiscountCodeAsync("ev_1", new EventDiscountCodeCreateRequest
            {
                Code = "EARLY10", Kind = "percent", Percent = 10,
            }));
        await Assert.ThrowsAsync<SeatLayerRateLimitException>(
            () => client.Events.ReplaceEventBookingFeeAsync("ev_1", 250));
        await Assert.ThrowsAsync<SeatLayerRateLimitException>(
            () => client.Orders.ResendEventOrderTicketsAsync("ev_1", "ord_1", "fan@example.com"));

        Assert.Equal(3, handler.Calls.Count);
        Assert.All(handler.Calls, call => Assert.False(call.Headers.Contains("Idempotency-Key")));
    }

    [Fact]
    public async Task RefundReplaysWithTheCallerKey()
    {
        var (client, handler) = Build(new[] { RateLimited(), Ok() }, maxRetries: 2);

        await client.Orders.RefundEventOrderAsync(
            "ev_1", "ord_1", new OrderRefundRequest { AmountMinor = 500, IdempotencyKey = "refund-7" });

        Assert.Equal(2, handler.Calls.Count);
        Assert.All(
            handler.Calls,
            call => Assert.Equal("refund-7", call.Headers.GetValues("Idempotency-Key").Single()));
    }

    [Fact]
    public async Task HolderRenewalCheckoutReplaysWithOneGeneratedKeyButDeclineIsSentOnce()
    {
        var (client, handler) = Build(
            new[] { RateLimited(), Created("{\"orderId\":\"ord_1\"}"), RateLimited() }, maxRetries: 3);

        var result = await client.Holders.CreateHolderRenewalCheckoutAsync(
            "a/b", "offer_1", new SeasonRenewalCheckoutRequest { ReturnUrl = "https://tickets.example/r" });
        await Assert.ThrowsAsync<SeatLayerRateLimitException>(
            () => client.Holders.DeclineHolderRenewalOfferAsync("a/b", "offer_1", "Moving away"));

        Assert.Contains("orderId", result);
        Assert.Equal(3, handler.Calls.Count);
        for (var index = 0; index < 2; index++)
        {
            AssertCall(handler, index, HttpMethod.Post,
                "https://api.seatlayer.io/v1/holders/a%2Fb/renewal-offers/offer_1/checkout",
                "{\"returnUrl\":\"https://tickets.example/r\"}", Generated);
        }

        Assert.Equal(
            handler.Calls[0].Headers.GetValues("Idempotency-Key").Single(),
            handler.Calls[1].Headers.GetValues("Idempotency-Key").Single());
        AssertCall(handler, 2, HttpMethod.Post,
            "https://api.seatlayer.io/v1/holders/a%2Fb/renewal-offers/offer_1/decline",
            "{\"reason\":\"Moving away\"}", null);
    }

    [Fact]
    public async Task HolderReturnReplaysWithOneGeneratedKey()
    {
        const string created =
            "{\"return\":{\"returnId\":\"ret_1\",\"state\":\"returned\",\"seasonKey\":\"sea_1\","
            + "\"tickets\":[],\"createdAt\":1}}";
        var (client, handler) = Build(new[] { RateLimited(), Created(created) }, maxRetries: 2);

        var result = await client.Holders.CreateHolderReturnAsync("a/b", new HolderReturnCreateRequest
        {
            TicketIds = new[] { "tkt_0123456789abcdef01234567" },
        });

        Assert.Contains("return", result);
        Assert.Equal(2, handler.Calls.Count);
        for (var index = 0; index < 2; index++)
        {
            AssertCall(handler, index, HttpMethod.Post, "https://api.seatlayer.io/v1/holders/a%2Fb/returns",
                "{\"ticketIds\":[\"tkt_0123456789abcdef01234567\"]}", Generated);
        }

        Assert.Equal(
            handler.Calls[0].Headers.GetValues("Idempotency-Key").Single(),
            handler.Calls[1].Headers.GetValues("Idempotency-Key").Single());
    }
}
